class Tangki {
public:
    int kapasitas;
    int isi = 0;

    int tuang(int liter) {
        int ruang = kapasitas - isi;
        if (liter > ruang) {
            liter = ruang;
        }
        isi += liter;
        return liter;
    }

    int pakai(int liter) {
        if (liter > isi) {
            liter = isi;
        }
        isi -= liter;
        return liter;
    }
};

