#include <iostream>
using namespace std;

class Polinom {
public:
    int derajat;
    int koef[10];

    long long nilai(int x) {
        long long hasil = 0;
        for (int k = derajat; k >= 0; k--) {
            hasil = hasil * x + koef[k];
        }
        return hasil;
    }

    Polinom turunan() {
        Polinom t;
        t.derajat = derajat - 1;
        if (t.derajat < 0) {
            t.derajat = 0;
            t.koef[0] = 0;
        }
        for (int k = 1; k <= derajat; k++) {
            t.koef[k - 1] = k * koef[k];
        }
        return t;
    }
};

int main() {
    Polinom p;
    int x;
    cin >> p.derajat;
    for (int k = p.derajat; k >= 0; k--) {
        cin >> p.koef[k];
    }
    cin >> x;
    cout << p.nilai(x) << endl;
    cout << p.turunan().nilai(x) << endl;
    return 0;
}

