class Tanggal {
public:
    int hari;
    int bulan;
    int tahun;

    static bool kabisat(int t) {
        return t % 400 == 0 || (t % 4 == 0 && t % 100 != 0);
    }

    int hariKe() {
        int hariBulan[12]{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (kabisat(tahun)) {
            hariBulan[1] = 29;
        }
        auto jumlah = hari;
        for (int b = 0; b < bulan - 1; b++) {
            jumlah += hariBulan[b];
        }
        return jumlah;
    }

    string namaHari() {
        auto total = hariKe() - 1;
        for (int t = 1900; t < tahun; t++) {
            total += 365;
            if (kabisat(t)) {
                total++;
            }
        }
        string nama[7]{"Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"};
        return nama[total % 7];
    }
};

