#include <iostream>
#include <string>
using namespace std;

class Rekening {
public:
    int saldo;

    void setor(int jumlah) {
        saldo += jumlah;
    }

    bool tarik(int jumlah) {
        if (jumlah > saldo) {
            return false;
        }
        saldo -= jumlah;
        return true;
    }

    bool transferKe(Rekening &tujuan, int jumlah) {
        if (!tarik(jumlah)) {
            return false;
        }
        tujuan.setor(jumlah);
        return true;
    }
};

int main() {
    int n;
    cin >> n;
    Rekening bank[6];
    for (int k = 0; k < n; k++) {
        cin >> bank[k].saldo;
    }
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        int a, b, jumlah;
        auto berhasil = true;
        if (perintah == "setor") {
            cin >> a >> jumlah;
            bank[a - 1].setor(jumlah);
        } else if (perintah == "tarik") {
            cin >> a >> jumlah;
            berhasil = bank[a - 1].tarik(jumlah);
        } else {
            cin >> a >> b >> jumlah;
            berhasil = bank[a - 1].transferKe(bank[b - 1], jumlah);
        }
        if (!berhasil) {
            cout << "Gagal" << endl;
        }
    }
    for (int k = 0; k < n; k++) {
        cout << "Rekening " << k + 1 << ": " << bank[k].saldo << endl;
    }
    return 0;
}

#include <iostream>
