class Robot {
public:
    int x = 0;
    int y = 0;
    int arah = 0;

    void kiri() {
        arah = (arah + 3) % 4;
    }

    void kanan() {
        arah = (arah + 1) % 4;
    }

    void maju() {
        switch (arah) {
            case 0: y++; break;
            case 1: x++; break;
            case 2: y--; break;
            default: x--; break;
        }
    }

    string namaArah() {
        string nama[4]{"utara", "timur", "selatan", "barat"};
        return nama[arah];
    }
};

int main() {
    string perintah;
    cin >> perintah;
    Robot robot;
    for (auto p : perintah) {
        if (p == 'M') {
            robot.maju();
        } else if (p == 'L') {
            robot.kiri();
        } else {
            robot.kanan();
        }
    }
    cout << robot.x << " " << robot.y << " " << robot.namaArah() << endl;
    return 0;
}

