import os
import random

r = random.Random(int(os.environ["SEED"]) * 1000 + int(os.environ["INDEX"]))
i = int(os.environ["INDEX"])
J = 'SHDC'
def kartu(nilai, jenis):
    return list(zip(nilai, jenis))
k = i % 9
if k == 0:
    a = r.randint(2, 10)
    t = kartu(range(a, a + 5), [r.choice(J)] * 5)
elif k == 1:
    a, b = r.sample(range(2, 15), 2)
    t = kartu([a] * 4 + [b], list(J) + [r.choice(J)])
elif k == 2:
    a, b = r.sample(range(2, 15), 2)
    t = kartu([a] * 3 + [b] * 2, r.sample(J, 3) + r.sample(J, 2))
elif k == 3:
    while True:
        v = sorted(r.sample(range(2, 15), 5))
        if v[4] - v[0] != 4:
            break
    t = kartu(v, [r.choice(J)] * 5)
elif k == 4:
    a = r.randint(2, 10)
    js = [r.choice(J) for _ in range(5)]
    js[1] = [x for x in J if x != js[0]][0]
    t = kartu(range(a, a + 5), js)
elif k == 5:
    a, b, c = r.sample(range(2, 15), 3)
    t = kartu([a] * 3 + [b, c], r.sample(J, 3) + [r.choice(J), r.choice(J)])
elif k == 6:
    a, b, c = r.sample(range(2, 15), 3)
    t = kartu([a] * 2 + [b] * 2 + [c], r.sample(J, 2) + r.sample(J, 2) + [r.choice(J)])
elif k == 7:
    a, b, c, d = r.sample(range(2, 15), 4)
    t = kartu([a] * 2 + [b, c, d], r.sample(J, 2) + [r.choice(J) for _ in range(3)])
else:
    while True:
        v = sorted(r.sample(range(2, 15), 5))
        if v[4] - v[0] != 4:
            break
    js = [r.choice(J) for _ in range(5)]
    js[1] = [x for x in J if x != js[0]][0]
    t = kartu(v, js)
t = list(t)
r.shuffle(t)
for n, j in t:
    print(n, j)

