#include <iostream>
#include <string>
using namespace std;

class TanganPoker {
public:
    int nilai[5];
    char jenis[5];

    bool sewarna() {
        for (int k = 1; k < 5; k++) {
            if (jenis[k] != jenis[0]) {
                return false;
            }
        }
        return true;
    }

    int banyakNilai(int n) {
        auto banyak = 0;
        for (auto v : nilai) {
            if (v == n) {
                banyak++;
            }
        }
        return banyak;
    }

    bool berurutan() {
        auto kecil = nilai[0];
        auto besar = nilai[0];
        for (auto v : nilai) {
            if (v < kecil) kecil = v;
            if (v > besar) besar = v;
            if (banyakNilai(v) != 1) {
                return false;
            }
        }
        return besar - kecil == 4;
    }

    string peringkat() {
        auto empat = 0;
        auto tiga = 0;
        auto pasang = 0;
        for (int n = 2; n <= 14; n++) {
            auto b = banyakNilai(n);
            if (b == 4) empat++;
            if (b == 3) tiga++;
            if (b == 2) pasang++;
        }
        if (berurutan() && sewarna()) return "straight flush";
        if (empat == 1) return "four of a kind";
        if (tiga == 1 && pasang == 1) return "full house";
        if (sewarna()) return "flush";
        if (berurutan()) return "straight";
        if (tiga == 1) return "three of a kind";
        if (pasang == 2) return "two pair";
        if (pasang == 1) return "one pair";
        return "high card";
    }
};

int main() {
    TanganPoker t;
    for (int k = 0; k < 5; k++) {
        cin >> t.nilai[k] >> t.jenis[k];
    }
    cout << t.peringkat() << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Penjadwal {
public:
    string nama[8];
    int sisa[8];
    int banyak = 0;
    int waktu = 0;

    void tambah(string n, int lama) {
        nama[banyak] = n;
        sisa[banyak] = lama;
        banyak++;
    }

    bool masihAda() {
        for (int k = 0; k < banyak; k++) {
            if (sisa[k] > 0) {
                return true;
            }
        }
        return false;
    }

    void putaran(int kuantum) {
        for (int k = 0; k < banyak; k++) {
            if (sisa[k] == 0) {
                continue;
            }
            auto jatah = kuantum;
            if (sisa[k] < jatah) {
                jatah = sisa[k];
            }
            sisa[k] -= jatah;
            waktu += jatah;
            if (sisa[k] == 0) {
                cout << nama[k] << " " << waktu << endl;
            }
        }
    }
};

int main() {
    int n, kuantum;
    cin >> n >> kuantum;
    Penjadwal p;
    for (int k = 0; k < n; k++) {
        string nama;
        int lama;
        cin >> nama >> lama;
        p.tambah(nama, lama);
    }
    while (p.masihAda()) {
        p.putaran(kuantum);
    }
    return 0;
}

#include <iostream>
using namespace std;

class BilanganBesar {
public:
    int digit[200];
    int panjang;

    void isi(int nilai) {
        panjang = 0;
        if (nilai == 0) {
            digit[0] = 0;
            panjang = 1;
        }
        while (nilai > 0) {
            digit[panjang] = nilai % 10;
            panjang++;
            nilai /= 10;
        }
    }

    void kali(int k) {
        auto simpan = 0;
        for (int p = 0; p < panjang; p++) {
            auto hasil = digit[p] * k + simpan;
            digit[p] = hasil % 10;
            simpan = hasil / 10;
        }
        while (simpan > 0) {
            digit[panjang] = simpan % 10;
            panjang++;
            simpan /= 10;
        }
    }

    void cetak() {
        for (int p = panjang - 1; p >= 0; p--) {
            cout << digit[p];
        }
        cout << endl;
    }
};

int main() {
    int n;
    cin >> n;
    BilanganBesar f;
    f.isi(1);
    for (int k = 2; k <= n; k++) {
        f.kali(k);
    }
    f.cetak();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class MesinPenjual {
public:
    string nama[5];
    int harga[5];
    int stok[5];
    int banyak = 0;
    int saldo = 0;
    int pendapatan = 0;

    void isiSlot(string n, int h, int s) {
        nama[banyak] = n;
        harga[banyak] = h;
        stok[banyak] = s;
        banyak++;
    }

    void masukkan(int uang) {
        saldo += uang;
    }

    void pilih(int nomor) {
        auto k = nomor - 1;
        if (stok[k] == 0) {
            cout << "Habis" << endl;
        } else if (saldo < harga[k]) {
            cout << "Uang kurang" << endl;
        } else {
            stok[k]--;
            saldo -= harga[k];
            pendapatan += harga[k];
            cout << "Keluar: " << nama[k] << endl;
        }
    }

    void batal() {
        cout << "Kembali: " << saldo << endl;
        saldo = 0;
    }
};

int main() {
    int k;
    cin >> k;
    MesinPenjual mesin;
    for (int s = 0; s < k; s++) {
        string nama;
        int harga, stok;
        cin >> nama >> harga >> stok;
        mesin.isiSlot(nama, harga, stok);
    }
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        if (perintah == "batal") {
            mesin.batal();
        } else {
            int x;
            cin >> x;
            if (perintah == "uang") {
                mesin.masukkan(x);
            } else {
                mesin.pilih(x);
            }
        }
    }
    cout << "Pendapatan: " << mesin.pendapatan << endl;
    return 0;
}
